import { ok, fail } from './result.js';
import { getCustomer } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';

/**
 * Check if a string is a valid date in YYYY-MM-DD format and represents a real date.
 * @param {string} dateStr
 * @returns {boolean}
 */
function isValidDate(dateStr) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(dateStr));
  if (!match) return false;

  const [, year, month, day] = match;
  const date = new Date(`${year}-${month}-${day}T00:00:00Z`);

  // Verify the parsed date matches the input (catches invalid dates like 2000-02-30)
  return (
    date.getUTCFullYear() === Number(year) &&
    date.getUTCMonth() === Number(month) - 1 &&
    date.getUTCDate() === Number(day)
  );
}

/**
 * Check if a value is a positive integer.
 * @param {unknown} value
 * @returns {boolean}
 */
function isPositiveInteger(value) {
  return Number.isInteger(value) && value > 0;
}

/**
 * Check if a value is a valid discount percent (0-100, can be decimal).
 * @param {unknown} value
 * @returns {boolean}
 */
function isValidDiscountPercent(value) {
  return typeof value === 'number' && value >= 0 && value <= 100;
}

/**
 * Create an invoice with the given customer, issue date, and line items.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }> }} input
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: 'draft', lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  // Validate customer
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return customerResult;

  // Validate date
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate lines array is not empty
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Build and validate line items
  const invoiceLines = [];
  for (const line of lines) {
    // Validate qty
    if (!isPositiveInteger(line.qty)) return fail('QTY_INVALID');

    // Validate discountPercent if provided
    const discountPercent = line.discountPercent ?? 0;
    if (!isValidDiscountPercent(discountPercent)) return fail('DISCOUNT_INVALID');

    // Get product from catalogue
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    invoiceLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  const invoice = {
    customerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
  };

  return ok(invoice);
}

/**
 * Calculate the total for a single line item: qty × unitPrice (in cents).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number }> }} invoice
 * @returns {{ subtotal: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  return {
    subtotal,
    total: subtotal,
  };
}

/**
 * Add or update a line on a draft invoice.
 * @param {{ status: string, lines: Array<{ sku: string, qty: number, name: string, unitPrice: number, vatRate: number }> }} invoice
 * @param {{ sku: string, qty: number }} input
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty }) {
  // Check if invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty
  if (!isPositiveInteger(qty)) return fail('QTY_INVALID');

  // Get product from catalogue to validate SKU
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;

  // Create new lines array
  const newLines = invoice.lines.map((line) => ({ ...line }));
  const existingIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingIndex >= 0) {
    // Update existing line
    newLines[existingIndex] = {
      ...newLines[existingIndex],
      qty: newLines[existingIndex].qty + qty,
    };
  } else {
    // Add new line
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    });
  }

  const newInvoice = {
    ...invoice,
    lines: newLines,
  };

  return ok(newInvoice);
}

/**
 * Remove a line from a draft invoice.
 * @param {{ status: string, lines: Array<{ sku: string }> }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check if invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Find the line to remove
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) return fail('LINE_NOT_FOUND');

  // Check if this is the last line
  if (invoice.lines.length === 1) return fail('NO_LINES');

  // Create new lines array without the removed line
  const newLines = invoice.lines.filter((line) => line.sku !== sku).map((line) => ({ ...line }));

  const newInvoice = {
    ...invoice,
    lines: newLines,
  };

  return ok(newInvoice);
}

/**
 * Issue a draft invoice, assigning it a number and changing status to 'issued'.
 * @param {{ status: string, issueDate: string }} invoice
 * @param {string[]} existingNumbers - Array of invoice numbers already used
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check if invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  const newInvoice = {
    ...invoice,
    number,
    status: 'issued',
  };

  return ok(newInvoice);
}

